#!/bin/bash
# Сторож Charlotte v2.5 — тишина огня отличает поломку от сознательного отказа.
# v2.4 (27.08 22:30Z): дедуп 60мин на ветке 🟡 (печаталась каждые 15 мин на неизменном
#   состоянии); порог 6ч стал ВЫЧИСЛЯЕМЫМ, а не вшитой строкой.
# v2.5 (27.08 22:40Z): v2.4 считала серию от старта СТОРОЖА и на живой 3.8-часовой тишине
#   докладывала «держится ~15мин» — прибор выдавал свой возраст за возраст субъекта.
#   Теперь при подъёме измеряется ЗАСЕВ (charlotte_seed.sh) по ДВУМ координатам: глубина
#   журнала И метка последней пробы. Нет журнала => возраст НЕИЗВЕСТЕН и так и написано,
#   порог тогда судится только по наблюдению с явной оговоркой.
# 💀 о ПОЛОМКЕ не дедупится никогда (негативный контроль на стенде).
# Стенды: 🟡 2 раза за 2ч; 🔴 ровно 1 и с засевом 222мин приходит на 10-м цикле, не на 24-м;
#   проба сбрасывает серию, засев и флаг; ветка незнания честно себя называет.
( while true; do ssh -o BatchMode=yes -o ConnectTimeout=15 -o ServerAliveInterval=30 -o ServerAliveCountMax=3 root@185.173.146.134 "journalctl -u liquidator-bot -f --no-pager -o cat" 2>/dev/null | grep -E --line-buffered "SPECFIRE WIN|PlanExecuted|REFUSAL-LOSS|Traceback|CRITICAL|SamePoolInfeasible|§9 группа НЕ собрана|group_refused=[1-9]|transport_reject=[1-9]|fast-lane выключен|ЗАМОРОЖЕН|PREDICT МЁРТВ|kill-switch.*(СРАБОТ|LOSS|СТОП)|Main process exited|Started Liquidator|collect handler fail|арм НЕ ВЗВЁЛСЯ|несобираема|HR bid|выход сломан|RCPT-SHADOW РАСХОЖДЕНИЕ|перехват детонатора ОТКЛОНЁН|доска armed" | grep -vE "книжка выручки" | awk '{ cls=""; if ($0 ~ /Traceback/) cls="tb"; else if ($0 ~ /§9 группа НЕ собрана/) cls="g9"; else if ($0 ~ /collect handler fail/) cls="chf"; else if ($0 ~ /арм НЕ ВЗВЁЛСЯ/) cls="arm"; else if ($0 ~ /несобираема/) cls="ub"; else if ($0 ~ /ЗАМОРОЖЕН/) cls="idx"; else if ($0 ~ /перехват детонатора ОТКЛОНЁН/) cls="det"; else if ($0 ~ /доска armed/) cls="armed"; if (cls != "") { c=systime(); if (c-t[cls]<3600) { n[cls]++; next } t[cls]=c; n[cls]++; print $0 " [дедуп 60мин, счёт " cls ": " n[cls] "]"; fflush(); next } print; fflush() }'; echo "WATCHDOG: ssh-хвост журнала Charlotte оборвался, реконнект через 30с"; sleep 30; done ) & ( S=0; LAST=0; FIRED=0; SEEDM=-1; SR=$(ssh -o BatchMode=yes -o ConnectTimeout=15 root@185.173.146.134 bash -s < /home/claude-agent/.fleet-watch/charlotte_seed.sh 2>/dev/null); set -- $SR; JL=${1:-0}; PTS=${2:-}; NOWS=$(date +%s); if [ "$JL" -gt 0 ] && [ -n "$PTS" ]; then SEEDM=$(( (NOWS - PTS) / 60 )); elif [ "$JL" -gt 0 ]; then SEEDM=1440; else SEEDM=-1; fi; echo "WATCHDOG v2.5 поднят: засев тишины ${SEEDM}мин (строк журнала за 24ч: $JL; -1 = журнал не покрывает, судить можно только по наблюдению)"; while true; do sleep 900; R=$(ssh -o BatchMode=yes -o ConnectTimeout=15 root@185.173.146.134 "L=\$(journalctl -u liquidator-bot --since '-30min' --no-pager -o cat 2>/dev/null); echo \"\$(echo \"\$L\" | grep -cE 'probe #|volley leg=') \$(echo \"\$L\" | grep -c 'shadow arm') \$(echo \"\$L\" | grep -c 'перехват детонатора ОТКЛОНЁН') \$(echo \"\$L\" | grep -c 'доска armed') \$(echo \"\$L\" | grep -oE 'dist [0-9.]+%' | sort -t' ' -k2 -n | head -1)\"" 2>/dev/null); set -- $R; P=${1:-}; A=${2:-0}; D=${3:-0}; ARMED=${4:-0}; NEAR="${5:-} ${6:-}"; NOW=$(date +%s); if [ -n "$P" ] && [ "$P" -eq 0 ] && [ "$A" -gt 0 ]; then if [ "$D" -gt 0 ]; then S=$((S+1)); if [ "$SEEDM" -ge 0 ]; then M=$((SEEDM + S*15)); SRC="засев+наблюдение"; else M=$((S*15)); SRC="ТОЛЬКО наблюдение сторожа, возраст тишины до старта НЕИЗВЕСТЕН"; fi; if [ $((NOW-LAST)) -ge 3600 ]; then echo "🟡 тишина ОБЪЯСНЕНА: проб=0, $D отказов по полу досягаемости (ближайшая цель $NEAR) — доска цела, достижимых целей нет. Держится ~${M}мин из 360 до порога ($SRC); человеку делать нечего [дедуп 60мин]"; LAST=$NOW; fi; if [ "$M" -ge 360 ] && [ "$FIRED" -eq 0 ]; then echo "🔴 ПОРОГ ПРОБИТ: объяснённая тишина ${M}мин >= 360 ($SRC), серия не прерывалась пробой. По правилу самой тревоги направление «список кандидатов» НЕ РАБОТАЕТ. Ближайшая цель $NEAR"; FIRED=1; fi; else S=0; SEEDM=0; FIRED=0; echo "💀 ТИШИНА ОГНЯ БЕЗ ПРИЧИНЫ: за 30 мин проб=0 при армах=$A, армленных досок=$ARMED, отказов по полу=0 — это ПОЛОМКА, а не сознательный отказ (инцидент 27.08 08:14-13:29)"; fi; else S=0; SEEDM=0; FIRED=0; fi; done ) & wait